export class AuthorsResolver {
  constructor(private readonly posts: PostsService) {}

  @ResolveField(() => [Post])
  async postsFor(@Parent() author: Author) {
    // BUG: one query PER author -> the GraphQL N+1
    return this.posts.findByAuthorId(author.id);
  }
}

model.en:
// The resolver just enqueues a key:
@ResolveField(() => [Post])
postsFor(@Parent() author: Author) {
  return this.loader.byAuthorId.load(author.id);
}

// The per-request loader batches the keys:
@Injectable({ scope: Scope.REQUEST })
export class PostsLoader {
  constructor(private readonly posts: PostsService) {}
  readonly byAuthorId = new DataLoader<number, Post[]>(async (authorIds) => {
    const rows = await this.posts.findByAuthorIds(authorIds as number[]); // ONE call
    const byId = new Map<number, Post[]>(authorIds.map((id) => [id, []]));
    for (const p of rows) byId.get(p.authorId)!.push(p);
    return authorIds.map((id) => byId.get(id)!); // SAME order as keys
  });
}

Why: load(id) enqueues a key instead of querying; all keys collected in one tick are batched into a single findByAuthorIds([...]) call, turning 1 + N into 1 + 1. The loader is Scope.REQUEST so its cache never leaks across users. The batch function MUST return an array the same length and order as the input keys (missing key -> []), or authors get each other's posts.

