// Резолвер просто ставит ключ в очередь:
@ResolveField(() => [Post])
postsFor(@Parent() author: Author) {
  return this.loader.byAuthorId.load(author.id);
}

// Loader на запрос батчит ключи:
@Injectable({ scope: Scope.REQUEST })
export class PostsLoader {
  constructor(private readonly posts: PostsService) {}
  readonly byAuthorId = new DataLoader<number, Post[]>(async (authorIds) => {
    const rows = await this.posts.findByAuthorIds(authorIds as number[]); // ОДИН вызов
    const byId = new Map<number, Post[]>(authorIds.map((id) => [id, []]));
    for (const p of rows) byId.get(p.authorId)!.push(p);
    return authorIds.map((id) => byId.get(id)!); // ТОТ ЖЕ порядок, что у ключей
  });
}

Почему: load(id) ставит ключ в очередь вместо запроса; все ключи, собранные за один тик, батчатся в единственный вызов findByAuthorIds([...]), превращая 1 + N в 1 + 1. Loader — Scope.REQUEST, так что его кэш никогда не утекает между пользователями. Batch-функция ОБЯЗАНА вернуть массив той же длины и порядка, что и входные ключи (отсутствующий ключ -> []), иначе авторы получат чужие посты.
